def best_trips(prices, k, fee):
    k = min(k, len(prices) // 2)
    if k == 0:
        return 0
    hold = [-prices[0]] * (k + 1)
    free = [0] * (k + 1)
    for p in prices[1:]:
        for j in range(k, 0, -1):
            free[j] = max(free[j], hold[j] + p - fee)
            hold[j] = max(hold[j], free[j - 1] - p)
    return max(free)

