def best_trips(prices, k, fee):
    free, hold = 0, -prices[0]
    for p in prices[1:]:
        free, hold = max(free, hold + p - fee), max(hold, free - p)
    return free

def best_trips(prices, k, fee):
    gains = []
    low = prices[0]
    for a, b in zip(prices, prices[1:] + [0]):
        if b < a:
            if a - low > fee:
                gains.append(a - low - fee)
            low = b
    gains.sort(reverse=True)
    return sum(gains[:k])

def best_trips(prices, k, fee):
    n = len(prices)

    def go(i, left, holding):
        if i == n:
            return 0 if not holding else -10 ** 9
        best = go(i + 1, left, holding)
        if holding:
            best = max(best, prices[i] - fee + go(i + 1, left, False))
        elif left:
            best = max(best, go(i + 1, left - 1, True) - prices[i])
        return best

    return go(0, k, False)
